// pi-ai's deep entry points for extensions running in pi-jsrt (virtual module `pi-rs:ai-subpaths`).
//
// `@earendil-works/pi-ai/providers/*`, `/api/*`, `/utils/*`, `/bedrock-provider` and `/bun-oauth`
// are small modules generated by `ai_subpaths.rs` that re-export names from here. This module
// re-exports the pi-ai glue (`pi-rs:ai-core`, `pi-rs:ai-faux`, `pi-rs:ai-rust`) and adds what
// the root entry point does not export: built-in provider factories and catalogs, the per-API
// `stream`/`classify` functions, and pi-ai's internal helpers. Helpers with real logic call
// the Rust pi-ai crate (`sub.*` host calls); one-line helpers are ported here. Exports that
// cannot work in pi-rs throw `PiRsUnsupportedError` when used.

import { call, callAsync, u } from "pi-rs:bridge";
import { ModelsError, isModelType } from "pi-rs:ai-core";
