/** A freshly constructed built-in provider (the Rust provider), as `<id>Provider()` returns. */
export function builtinProvider(id) {
	return globalThis.__piAiRust.providerFromDesc(call("aip.builtinProvider", { id }));
}

const CATALOG_READERS = { chat: getBuiltinModels, image: getBuiltinImageModels, classifier: getBuiltinClassifierModels };

/** A provider's static catalog keyed by model id (`<PREFIX>_MODELS`, `_IMAGE_MODELS`, `_CLASSIFIER_MODELS`). */
export function builtinCatalog(id, kind) {
	return Object.fromEntries(CATALOG_READERS[kind](id).map((model) => [model.id, model]));
}

