/** A built-in classifier API (Rust) as a `ProviderClassifier`. */
function nativeClassifier(api) {
	const id = call("aip.classifierApi", { api });
	return {
		classify: async (model, context, options) =>
			await callAsync("aip.p.classify", { id, model, context, options: optionsToRust(options) }),
	};
}
export const openAIDecisionsApi = () => nativeClassifier("openai-decisions");
