export const typesafeSystemOneApi = () => nativeClassifier("typesafe-system-one");
export const cloudflareWorkersAISystemOneApi = () => nativeClassifier("cloudflare-workers-ai-system-one");
const classifierFunction = (api) => {
	let classifier;
	return (model, context, options) => (classifier ??= nativeClassifier(api)).classify(model, context, options);
};
export const openAIDecisionsClassify = classifierFunction("openai-decisions");
export const llamaCppClassify = classifierFunction("llama-cpp-classify");
