export function makeStrictJsonSchema(schema, isUnsupportedKeyword) {
	if (isUnsupportedKeyword !== undefined) {
		throw new PiRsUnsupportedError(
			"@earendil-works/pi-ai/api/constrained-sampling",
			"makeStrictJsonSchema",
			"a JavaScript isUnsupportedKeyword check cannot run inside the Rust implementation",
		);
	}
	return sub("makeStrictJsonSchema", schema);
}
export const getJsonSchemaToolParameters = (tool, strict) => sub("getJsonSchemaToolParameters", tool, strict);
export function resolveJsonSchemaStrictSampling(tool, supportsStrictMode, isUnsupportedKeyword) {
	if (isUnsupportedKeyword !== undefined) {
		throw new PiRsUnsupportedError(
			"@earendil-works/pi-ai/api/constrained-sampling",
			"resolveJsonSchemaStrictSampling",
			"a JavaScript isUnsupportedKeyword check cannot run inside the Rust implementation",
		);
	}
	return sub("resolveJsonSchemaStrictSampling", tool, supportsStrictMode);
}
export const resolveGrammarConstrainedSampling = (tool, supportsOpenAIGrammarTools) =>
	sub("resolveGrammarConstrainedSampling", tool, supportsOpenAIGrammarTools);
export function getGrammarToolInput(toolName, arguments_, inputProperty) {
	const input = arguments_[inputProperty];
	if (typeof input !== "string") {
		throw new Error(`Grammar tool call "${toolName}" requires argument "${inputProperty}" to be a string.`);
	}
	return input;
}
export function appendGrammarToolInputJsonDelta(buffer, inputProperty, nextInput, close) {
	if (buffer.closed) {
		if (close && nextInput === buffer.input) return undefined;
		throw new Error(`grammar tool input for property "${inputProperty}" changed after it was closed`);
	}
	if (!nextInput.startsWith(buffer.input)) {
		throw new Error(`grammar tool input for property "${inputProperty}" changed non-monotonically`);
	}
	const inputDelta = nextInput.slice(buffer.input.length);
	if (!close && inputDelta.length === 0) return undefined;
	let delta = "";
	if (!buffer.started) {
		delta += `{${JSON.stringify(inputProperty)}:"`;
		buffer.started = true;
	}
	delta += JSON.stringify(inputDelta).slice(1, -1);
	buffer.input = nextInput;
	if (close) {
		delta += '"}';
		buffer.closed = true;
	}
	return delta;
}
export function createGrammarToolInputProperties(tools, supportsOpenAIGrammarTools) {
	const properties = new Map();
	for (const tool of tools ?? []) {
		const grammar = resolveGrammarConstrainedSampling(tool, supportsOpenAIGrammarTools);
		if (grammar) properties.set(tool.name, grammar.inputProperty);
	}
	return properties;
}

// api/github-copilot-headers.ts
export function inferCopilotInitiator(messages) {
	const last = messages[messages.length - 1];
	return last && last.role !== "user" ? "agent" : "user";
}
export function hasCopilotVisionInput(messages) {
	return messages.some((msg) => {
		if (msg.role === "user" && Array.isArray(msg.content)) return msg.content.some((c) => c.type === "image");
		if (msg.role === "toolResult" && Array.isArray(msg.content)) return msg.content.some((c) => c.type === "image");
		return false;
	});
}
