// api/llama-cpp-classify.ts
export const llamaServerRoot = (baseUrl) => baseUrl.replace(/\/+$/u, "").replace(/\/v1$/u, "");
export function labelProbabilities(logprobs, temperature) {
	const scaled = logprobs.map((logprob) => logprob / temperature);
	const max = Math.max(...scaled);
	const weights = scaled.map((value) => Math.exp(value - max));
	const total = weights.reduce((sum, weight) => sum + weight, 0);
	return weights.map((weight) => weight / total);
}
export function peakConfidence(probabilities) {
	const n = probabilities.length;
	const peak = Math.max(...probabilities);
	return Math.min(1, Math.max(0, (n * peak - 1) / (n - 1)));
}
