// utils/abort-signals.ts
export function combineAbortSignals(signals) {
	const activeSignals = signals.filter((signal) => signal !== undefined);
	if (activeSignals.length === 0) return { cleanup: () => {} };
	if (activeSignals.length === 1) return { signal: activeSignals[0], cleanup: () => {} };
	const controller = new AbortController();
	const listeners = [];
	const abort = (signal) => {
		if (!controller.signal.aborted) controller.abort(signal.reason);
	};
	for (const signal of activeSignals) {
		if (signal.aborted) {
			abort(signal);
			break;
		}
		const listener = () => abort(signal);
		signal.addEventListener("abort", listener, { once: true });
		listeners.push({ signal, listener });
	}
	return {
		signal: controller.signal,
		cleanup: () => {
			for (const { signal, listener } of listeners) signal.removeEventListener("abort", listener);
		},
	};
}

// utils/error-body.ts
export const MAX_PROVIDER_ERROR_BODY_CHARS = constants.MAX_PROVIDER_ERROR_BODY_CHARS;
export function safeJsonStringify(value) {
	try {
		const serialized = JSON.stringify(value);
		return serialized === undefined ? String(value) : serialized;
	} catch {
		return String(value);
	}
}
export function truncateErrorText(text, maxChars) {
	if (text.length <= maxChars) return text;
	return `${text.slice(0, maxChars)}... [truncated ${text.length - maxChars} chars]`;
}
function isPlainNonEmptyObject(value) {
	if (typeof value !== "object" || value === null) return false;
	const proto = Object.getPrototypeOf(value);
	if (proto !== Object.prototype && proto !== null) return false;
	return Object.keys(value).length > 0;
}
function pickBodyText(error) {
	if (typeof error.body === "string") return error.body;
	if (isPlainNonEmptyObject(error.error)) return safeJsonStringify(error.error);
	const responseBody = error.$response?.body;
	if (typeof responseBody === "string") return responseBody;
	if (typeof responseBody === "object" && responseBody !== null && typeof responseBody.pipe === "function") {
		return undefined;
	}
	if (isPlainNonEmptyObject(responseBody)) return safeJsonStringify(responseBody);
	return undefined;
}
/** Status, body and message of a provider SDK error (Mistral, OpenAI, Google, Bedrock shapes). */
export function normalizeProviderError(error) {
	if (!(error instanceof Error)) return { message: safeJsonStringify(error), messageCarriesBody: false };
	let status;
	if (typeof error.statusCode === "number") status = error.statusCode;
	else if (typeof error.status === "number") status = error.status;
	else if (typeof error.$metadata?.httpStatusCode === "number") status = error.$metadata.httpStatusCode;
	else if (typeof error.$response?.statusCode === "number") status = error.$response.statusCode;
	const trimmed = pickBodyText(error)?.trim();
	const body = trimmed ? truncateErrorText(trimmed, MAX_PROVIDER_ERROR_BODY_CHARS) : undefined;
	return { status, body, message: error.message, messageCarriesBody: body === undefined || error.message.includes(body) };
}
export function formatProviderError(norm, prefix) {
	if (norm.messageCarriesBody || norm.status === undefined || norm.body === undefined) {
		return prefix !== undefined && norm.status !== undefined ? `${prefix} (${norm.status}): ${norm.message}` : norm.message;
	}
	return prefix !== undefined ? `${prefix} (${norm.status}): ${norm.body}` : `${norm.status}: ${norm.body}`;
}

// utils/estimate.ts
const CHARS_PER_TOKEN = 3.5;
export const calculateContextTokens = (usage) =>
	usage.totalTokens || usage.input + usage.output + usage.cacheRead + usage.cacheWrite;
export const estimateTextTokens = (text) => Math.ceil(text.length / CHARS_PER_TOKEN);
export const estimateTextAndImageContentTokens = (content) => sub("estimateTextAndImageContentTokens", content);
export const estimateMessageTokens = (message) => sub("estimateMessageTokens", message);
export const estimateContextTokens = (context) => sub("estimateContextTokens", context);

// utils/hash.ts
/** Fast deterministic hash to shorten long strings. */
export function shortHash(str) {
	let h1 = 0xdeadbeef;
	let h2 = 0x41c6ce57;
	for (let i = 0; i < str.length; i++) {
		const ch = str.charCodeAt(i);
		h1 = Math.imul(h1 ^ ch, 2654435761);
		h2 = Math.imul(h2 ^ ch, 1597334677);
	}
	h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
	h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
	return (h2 >>> 0).toString(36) + (h1 >>> 0).toString(36);
}

// utils/headers.ts
export function headersToRecord(headers) {
	const result = {};
	for (const [key, value] of headers.entries()) result[key] = value;
	return result;
}
export function providerHeadersToRecord(...headerSources) {
	const merged = new Map();
	for (const source of headerSources) {
		for (const [name, value] of Object.entries(source ?? {})) {
			const normalizedName = name.toLowerCase();
			merged.delete(normalizedName);
			if (value !== null) merged.set(normalizedName, [name, value]);
		}
	}
	return merged.size > 0 ? Object.fromEntries(merged.values()) : undefined;
}

// utils/model-operations.ts
export function assertChatModel(model) {
	if (!isModelType(model, "chat")) throw new ModelsError("provider", `Model ${model.provider}/${model.id} is not a chat model`);
}
export function assertImageModel(model) {
	if (!isModelType(model, "image")) throw new ModelsError("provider", `Model ${model.provider}/${model.id} is not an image model`);
}
export function assertClassifierModel(model) {
	if (!isModelType(model, "classifier")) {
		throw new ModelsError("provider", `Model ${model.provider}/${model.id} is not a classifier model`);
	}
}
export function assertClassifierInputSupported(model, context) {
	if (context.images?.length && !model.input.includes("image")) {
		throw new ModelsError("provider", `Model ${model.provider}/${model.id} does not accept image input`);
	}
}

// utils/node-http-proxy.ts
export const UNSUPPORTED_PROXY_PROTOCOL_MESSAGE = constants.UNSUPPORTED_PROXY_PROTOCOL_MESSAGE;
export function resolveHttpProxyUrlForTarget(targetUrl, env) {
	const proxy = sub("resolveHttpProxyUrlForTarget", String(targetUrl), env);
	return proxy === undefined ? undefined : new URL(proxy);
}

// utils/oauth-page.ts
export const oauthSuccessHtml = (message) => sub("oauthSuccessHtml", message);
export const oauthErrorHtml = (message, details) => sub("oauthErrorHtml", message, details);

// utils/provider-env.ts
export function getProviderEnvValue(name, env) {
	return env?.[name] || (typeof process !== "undefined" ? process.env[name] : undefined) || undefined;
}

// utils/provider-retry.ts
export const retryProviderRequest = unsupported(
	"utils/provider-retry",
	"retryProviderRequest",
	"provider request retries run inside the Rust API implementations",
);

// utils/sanitize-unicode.ts
export function sanitizeSurrogates(text) {
	return text.replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g, "");
}

// utils/sleep.ts
export function sleep(ms, signal) {
	return new Promise((resolve, reject) => {
		signal.throwIfAborted();
		const onAbort = () => {
			clearTimeout(timeout);
			reject(signal.reason);
		};
		const timeout = setTimeout(() => {
			signal.removeEventListener("abort", onAbort);
			resolve();
		}, ms);
		signal.addEventListener("abort", onAbort, { once: true });
	});
}

